# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
-- The sheet's periods: a name, unique on the sheet without regard to case (name_key is the trimmed,
-- lower-cased name), and a from and to date, both inclusive, from on or before to. No two of a
-- sheet's periods overlap. A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
import { Component, inject } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';
import { SheetPicker } from '../session/sheet-picker';
import { SheetToday } from '../session/sheet-today';
import { SignIn } from '../session/sign-in';

// The one screen: sign in, then choose a sheet; everything else is kept per sheet.
@Component({
  selector: 'app-home',
  imports: [SignIn, SheetPicker, SheetToday, People],
  template: `
    @if (session.user(); as user) {
      <header>
        Signed in as <strong data-testid="current-user">{{ user }}</strong>
      </header>
      <app-sheet-picker />
      <app-sheet-today />
      <app-people />
      @if (!session.sheet()) {
        <p data-testid="home-empty">Load a sheet to begin.</p>
      }
    } @else {
      <app-sign-in />
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
}
import { Component, computed, effect, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { GRADES, Grade } from '../people/people-api';
import { RateView, RatesApi, rateInForce } from './rates-api';

const PCT = /^\d{1,3}(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's rate in force today for each grade, and every rate with its from-date, with one form
// to set a grade's rate from a from-date.
@Component({
  selector: 'app-rates',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Set a rate">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" formControlName="pct" inputmode="decimal" />
        <label for="rate-form-from">From (blank: from the start)</label>
        <input id="rate-form-from" type="date" data-testid="rate-form-from" formControlName="from" />
        <button type="submit" data-testid="rate-form-submit" [disabled]="saving()">Set rate</button>
        @if (error()) {
          <p role="alert" data-testid="rate-form-error">{{ error() }}</p>
        }
      </form>
      <table aria-label="Rates in force today">
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">Rate today (%)</th></tr>
        </thead>
        <tbody>
          @for (g of grades; track g) {
            <tr>
              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">{{ currentOf(g) }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="rates-list" aria-label="All rates">
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">From</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (r of rates(); track r.grade + (r.from ?? 'start')) {
            <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
              <th scope="row">{{ r.grade }}</th>
              <td data-testid="rate-from">{{ r.from ?? 'start' }}</td>
              <td data-testid="rate-pct">{{ r.pct }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Rates {
  private readonly session = inject(Session);
  private readonly api = inject(RatesApi);

  /** The sheet's rates, in grade order then by from-date; a grade with no rate is left out. */
  readonly rates = input.required<RateView[]>();
  readonly saved = output<RateView>();

  protected readonly grades = GRADES;
  protected readonly grade = new FormControl<Grade>('A', { nonNullable: true });
  protected readonly pct = new FormControl('', { nonNullable: true });
  protected readonly from = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ grade: this.grade, pct: this.pct, from: this.from });
  protected readonly saving = signal(false);
  protected readonly error = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    // Each load of a sheet starts the form without the error from the last one.
    effect(() => {
      this.session.loaded();
      this.error.set('');
    });
  }

  private readonly today = computed(() => this.session.sheet()?.today ?? null);

  /** The grade's rate in force on the sheet's today, or n/a when none is. */
  protected currentOf(grade: Grade): string {
    const today = this.today();
    const rate = today === null ? null : rateInForce(this.rates().filter((r) => r.grade === grade), today);
